    void Start()
    {
        MeasureFunctionExecutionTime();
        MeasureManagedFunctionExecutionTime();
    }

    void MeasureFunctionExecutionTime()
    {
        Stopwatch stopwatch = new Stopwatch();

        stopwatch.Start(); // Start timing
        MyFunctionToTest(); // Call the function you want to measure
        stopwatch.Stop();  // Stop timing

        // Get the elapsed time
        long elapsedMilliseconds = stopwatch.ElapsedMilliseconds;
        UnityEngine.Debug.Log($"MyFunctionToTest took {elapsedMilliseconds} ms to execute.");
    }

    void MeasureManagedFunctionExecutionTime()
    {
        Stopwatch stopwatch = new Stopwatch();

        stopwatch.Start(); // Start timing
        TestManaged(); // Call the function you want to measure
        stopwatch.Stop();  // Stop timing

        // Get the elapsed time
        long elapsedMilliseconds = stopwatch.ElapsedMilliseconds;
        UnityEngine.Debug.Log($"TestManaged took {elapsedMilliseconds} ms to execute.");
    }

    void MyFunctionToTest()
    {
        TestSort(a, a.Length);
    }

    void TestManaged()
    {
        Sorting.SortArray(b, b.Length);
    }
}
